<?php require_once __DIR__ . "/../includes/auth-check.php"; require_once __DIR__ . "/../Config/db.php"; require_once __DIR__ . "/../includes/ui.php"; $uid=(int)$_SESSION['user_id']; $reports=$conn->query("SELECT id,title,status,priority_score,ambulance_eta_minutes FROM reports WHERE user_id=$uid ORDER BY created_at DESC LIMIT 20"); sr_page_start('Track Report','track'); ?>
<div class="hero-card"><h2>Track emergency response</h2><p>Select a report to see the complete incident details and live status.</p></div><div class="card" style="margin-top:18px"><div class="grid grid-3"><?php if($reports && $reports->num_rows): while($r=$reports->fetch_assoc()): ?><a class="card" href="report-details.php?id=<?php echo (int)$r['id']; ?>"><h3>#<?php echo (int)$r['id']; ?> <?php echo htmlspecialchars($r['title']); ?></h3><p><?php echo sr_badge($r['status']); ?></p><p class="mini">Priority <?php echo (int)$r['priority_score']; ?>/100 · ETA <?php echo $r['ambulance_eta_minutes'] ?: 'N/A'; ?> min</p></a><?php endwhile; else: ?><div class="empty-state">No report to track.</div><?php endif; ?></div></div>
<?php sr_page_end(); ?>
